NWHOLE = sum(1 for vd, note in V.values() if '[whole:' in note and '; carried) — ' not in note[:200]); assert NWHOLE == TOT['corrected'] == 0, (NWHOLE, TOT); assert NCARRIED == len(CRED) - len(UNRES), (NCARRIED, len(CRED), len(UNRES))
